   "default": null,
   "constraints": []
  },
  {
   "name": "overwrite",
   "type": "boolean",
   "required": false,
   "description": "Whether to overwrite the decompressed directory if it already exists.",
   "default": false,
   "constraints": []
  },
  {
   "name": "retain_dates",
   "type": "boolean",
   "required": false,
   "description": "Whether the decompressed files should retain the created and updated dates of the files in the compressed file.",
   "default": true,
   "constraints": []
  },
  {
   "name": "delete_compressed_file",
   "type": "boolean",
   "required": false,
   "description": "Whether to delete the compressed file after decompression.",
   "default": false,
   "constraints": []
  }
 ],
 "response_schemas": {
